mapper.select:
select tppm.test_plugin_project_mount_id as testPluginProjectMountId, tppm.test_project_id as testProjectId, tppm.plugin_id as pluginId, tppm.mount_json as mountJson, tppm.del_status as delStatus, tppm.create_time as createTime, tppm.update_time as updateTime from test_plugin_project_mount tppm where tppm.del_status = 0
and tppm.test_project_id = #{testProjectId}
and tppm.plugin_id = #{pluginId}
and tppm.mount_json = #{mountJson}
order by tppm.test_plugin_project_mount_id desc

select count(1)
from test_plugin_project_mount tppm
where tppm.del_status = 0

    and tppm.test_project_id = #{testProjectId}


    and tppm.plugin_id = #{pluginId}


    and tppm.mount_json = #{mountJson}

select tppm.test_plugin_project_mount_id, tppm.test_project_id, tppm.plugin_id, tppm.mount_json, tppm.del_status, tppm.create_time, tppm.update_time from test_plugin_project_mount tppm where tppm.del_status = 0
and tppm.test_project_id = #{testProjectId}
and tppm.plugin_id = #{pluginId}
and tppm.mount_json = #{mountJson}
order by tppm.test_plugin_project_mount_id desc limit 1
